pair<double, double> findDiagonalProducts(vector<vector<double>>& mat) {
    int n = mat.size(); // matrix size

    double prod_main = 1.0, prod_sec = 1.0;

    for (int i = 0; i < n; i++) {
        // calculating product of main diagonal
        prod_main *= mat[i][i];

