Here is a solution to the problem. The function, mergeAndSort, proceeds in two stages, first merging the arrays and removing duplicates, and then sorting the resulting array in descending order using the bubble sort algorithm:

```javascript
function mergeAndSort(arr1, arr2) {
    // Merging arrays and removing duplicates
    let merged = [...new Set([...arr1, ...arr2])];

    // Sorting the merged array in descending order
    for (let i=0; i<merged.length; i++) {
        for (let j=i+1; j<merged.length; j++) {
            if (merged[j] > merged[i]) {
                let temp = merged[i];
                merged[i] = merged[j];
                merged[j] = temp;
            }
        }
    }

    return merged;
}

console.log(mergeAndSort([6, 4, 15, 10], [2, 9, 12, 3]));
