    for (var i = 0; i < words.length; i++) {
        var word = words[i];
        // Count the number of consonants in the word
        var nc = Array.from(word).reduce((count, char) => count + (consonants.includes(char.toLowerCase()) ? 1 : 0), 0);
        // Count the number of vowels in the word
        var nv = Array.from(word).reduce((count, char) => count + (vowels.includes(char.toLowerCase()) ? 1 : 0), 0);

        // Check if the word contains exactly `n` consonants and `m` vowels
        if (nc === n && nv === m) {
            // If word matches the last phrase and there's at least one vowel and one consonant
            if (temp_phrase === word && nc > 0 && nv > 0) {
                // Make word to array
                var wordArray = Array.from(word.toLowerCase());

                // Iterate through the word's characters
                for (var j = 0; j < wordArray.length; j++) {
                    var char = wordArray[j];
                    // If the character is a vowel and there are still vowels left to be removed
                    if (vowels.includes(char) && nv > 0) {
                        word = word.replace(char, '');
                        nv -= 1;
                    }
                    // If the character is a consonant and there are still consonants left to be removed
                    if (consonants.includes(char) && nc > 0) {
                        word = word.replace(char, '');
                        nc -= 1;
                    }
                }         
            }
