```javascript
class CurrencyConverter {
  constructor(api) {
    this.api = api;
    this.cache = {};
  }

  async getRate(from, to) {
    // Check the cache first.
    if (this.cache[`${from}_${to}`]) {
      return this.cache[`${from}_${to}`];
    }

    // Fetch the data from the API.
    let response = await fetch(`${this.api}/latest?base=${from}&symbols=${to}`);

    if (response.ok) {
      let rates = await response.json();
      this.cache[`${from}_${to}`] = rates.rates[to];
      return rates.rates[to];
    } else {
      throw new Error(`API Error: ${response.statusText}`);
    }
  }

  async convert(amount, from, to) {
    let rate = await this.getRate(from, to);
    return amount * rate;
  }

  async alertWhenRate(targetRate, from, to) {
    let rate = await this.getRate(from, to);
    if (rate >= targetRate) {
      alert(`Rate Alert! ${from} to ${to} hit ${targetRate}`);
    }
  }
}

// Usage

const converter = new CurrencyConverter('https://api.exchangerate-api.com');

async function convertCurrencies() {
  try {
    let usdToEur = await converter.convert(1000, 'USD', 'EUR');
