```cpp
#include <iostream>
#include <cctype>
using namespace std;

void countCharTypes(string str, int& vowels, int& consonants, int& digits, int& special, int& space) {
    for(int i = 0; i<str.length(); i++) {
        char c = tolower(str[i]);

        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u')
            vowels++;
        else if (c >= 'a' && c <= 'z')
            consonants++;
        else if (c >= '0' && c <= '9')
            digits++;
        else if (c == ' ')
            space++;
        else
            special++;
    }
}

int main() {
    string str = "Hello World!123";
    int vowels = 0, consonants = 0, digits = 0, special = 0, space = 0;

    countCharTypes(str, vowels, consonants, digits, special, space);

    cout << "Vowels : " << vowels << endl;
    cout << "Consonants : " << consonants << endl;
    cout << "Digits : " << digits << endl;
    cout << "Special characters : " << special << endl;
    cout << "Space : " << space << endl;

    return 0;
}
```

