import java.util.*;

public class ClientInfoMap {

    // Defining the HashMap with 'Email-id' as key and TransactionHistory List as Value
    private Map<String, List<String>> clientsInfoMap;

    // Initializing the HashMap in the Constructor
    public ClientInfoMap() {
        this.clientsInfoMap = new HashMap<>();
    }

    // Method to add new ClientInfo into the HashMap
    public void addClientInfo(String email, String transaction) {
        //If map already contains the email, add the transaction to the list
        if(clientsInfoMap.containsKey(email)) {
            this.clientsInfoMap.get(email).add(transaction);
        } 
        //If map does not contain the key, create a new list and add the transaction
        else {
            List<String> transactions = new LinkedList<>();
            transactions.add(transaction);
            this.clientsInfoMap.put(email, transactions);
        }
    }

    // Method to retrieve the transaction history of a client given his email

    public String getClientInfo(String email) {
        if(clientsInfoMap.containsKey(email)) {
            return clientsInfoMap.get(email).toString();
        }
        else
            return "No transactions found for this email!";
    }

}
