```python
import math

def complex_geometry_calculations(shape_parameters, shapes):
    def circle(radius):
        return math.pi * radius ** 2

    def rectangle(length, width):
        return length * width

    def triangle(base, height):
        return 0.5 * base * height

    def square(side):
        return side ** 2

    def parallelogram(base, height):
        return base * height

    def trapezoid(a, b, height):
        return (a + b) / 2 * height

    shape_functions = {
        "Circle": circle,
        "Rectangle": rectangle,
        "Triangle": triangle,
        "Square": square,
        "Parallelogram": parallelogram,
        "Trapezoid": trapezoid
    }

    if len(shapes) != len(shape_parameters):
        raise ValueError('Shapes list length should be equal to shape_parameters list length.')

    areas = []
    for i in range(len(shapes)):
        shape = shapes[i]
        parameters = shape_parameters[i]
        if shape in shape_functions:
            areas.append(shape_functions[shape](*parameters))

    return areas
