    /**
     * Checks if a value is within the specified range.
     *
     * @param value     The value to check.
     * @param lowerBound The lower bound of the range.
     * @param upperBound The upper bound of the range.
     * @param inclusive True if the range boundaries are inclusive, false if exclusive.
     * @return True if the value is within the range, false otherwise.
     * @throws IllegalArgumentException if lowerBound > upperBound
     */
    public static boolean isInRange(int value, int lowerBound, int upperBound, boolean inclusive) {
        if (lowerBound > upperBound) {
            throw new IllegalArgumentException("Invalid range: lowerBound > upperBound");
        }

        if (inclusive) {
            return value >= lowerBound && value <= upperBound;
        } else {
            return value > lowerBound && value < upperBound;
        }
    }
