            if(year % 4 == 0){
                // if year is divisible by 100, it is not a leap year, unless...
                if(year % 100 != 0 || year % 400 == 0){ 
                    // if year is also divisible by 400, then it is
                    System.out.println(year);
                    count++;
                    totalDays += (isLeap(year) ? 366 : 365);
                }
            }
        }
        float avg = totalDays/count;

        System.out.println("Total count of leap years: " + count);
        System.out.printf("Average total days in those leap years: %.2f\n", avg);
