import Foundation

func median<T: Comparable>(_ array: [T], _ compareFn: (T) -> T) -> Double? {
    // Declare mutable copy of array to perform sort in-place, as Swift array is a value type and not mutable.
    var arr = array

    // Sort array in-place using the custom comparison function passed in. As swift does not have an in-built sort with a custom function, fatalError is thrown in case of an error.
    // Feel free to replace this with your own error handling mechanism.
    do {
        try arr.sort {
            guard let v1 = $0 as? T, let v2 = $1 as? T else { throw NSError(domain: "", code: 101, userInfo: nil) }
            return compareFn(v1) < compareFn(v2)
        }
    } catch {
        // Handle error situation when compareFn is not properly defined.
        fatalError("compareFn must be a function that takes one argument and returns a key to sort the list.")
    }

    let len = arr.count

    // Handle odd-length array
    if len % 2 == 1 {
        return Double(arr[len / 2] as! Int)  // Return value at the midpoint
    }
    // Handle even-length array
    else {
        let i = len / 2
        // Return average of the two middle values
        return (Double(arr[i - 1] as! Int) + Double(arr[i] as! Int)) / 2
    }
}

func compareFn(x: Any) -> Any {
    // Custom comparison function for sorting tuples based on their sum.
    if let tup = x as? (Int, Int) {
        return tup.0 + tup.1 // sum of tuple
    }
    return x
}
