```C#
using System;
using System.Threading;
using System.Threading.Tasks;

public class EventPublisher
{
    private event Action<int> SomethingHappened;
    private readonly object _lock = new object();

    public void Register(Action<int> function)
    {
        lock (_lock)
        {
            SomethingHappened += function;
        }
    }

    public void UnRegister(Action<int> function)
    {
        lock (_lock)
        {
            SomethingHappened -= function;
        }
    }

    public async Task TriggerEventAsync(int value)
    {
        Action<int> handler;

        lock(_lock)
        {
            handler = SomethingHappened;
        }

        if(handler != null)
        {
            foreach(var singleCast in handler.GetInvocationList())
            {
                var singleHandler = (Action<int>) singleCast;
                try
                {
                    await Task.Run(() => singleHandler(value));
                }
                catch(Exception ex)
                {
                    Console.WriteLine(ex.Message);
                }
            }
        }
        else
        {
            Console.WriteLine("No subscribers available for the event.");
        }
    }
}

public class EventSubscriber
{
    public void OnSomethingHappened(int value)
    {
        Console.WriteLine("Value: " + value);
    }
}

class Program
{
    static void Main(string[] args)
    {
        var publisher = new EventPublisher();
        var subscriber = new EventSubscriber();

        publisher.Register(subscriber.OnSomethingHappened);
        publisher.TriggerEventAsync(5).Wait();

        publisher.UnRegister(subscriber.OnSomethingHappened);
        publisher.TriggerEventAsync(5).Wait();
    }
}
```

In this program, we have a class `EventPublisher` that publishes an event, and a class `EventSubscriber` that reacts to this event. 

The `EventPublisher` class uses a lock statement to ensure thread safety when adding or subtracting delegates from the event. 

In the `TriggerEventAsync` function, each delegate is called asynchronously inside a separate Task. If a delegate throws an exception, it is caught and printed to the console, but it does not prevent other delegates from being called. 

The `EventPublisher` also handles scenarios where no subscribers are available for the event by checking if the handler is not null before invoking it.

The `Main` function demonstrates the use of all these features - it adds a delegate to the event, triggers it, removes the delegate, and then triggers the event again. The second trigger displays a message that no subscribers are available for the event, demonstrating the handling of this scenario.

