```python
def split_list(l):
    subarrays = []
    normal_elements = []
    for element in l:
        if isinstance(element, list):
            subarrays.append(element)
        else:
            normal_elements.append(element)
    return subarrays, normal_elements

def bubble_sort(l):
    n = len(l)
    for i in range(n):
        for j in range(0, n - i - 1):
            if l[j] > l[j + 1] :
                l[j], l[j + 1] = l[j + 1], l[j]
    return l

def average(l):
    return sum(l) / len(l)

def solve(input_list):
    subarrays, normal_elements = split_list(input_list)
    sorted_subarrays = sorted([bubble_sort(subarray) for subarray in subarrays], key=average)
    sorted_elements = bubble_sort(normal_elements)
    return sorted_subarrays + sorted_elements

