```javascript
class GlobalTemperatures {
    constructor() {
        this.data = {
            "2016": [14.80, 12.97, 13.05, 13.71, 14.84, 16.32],
            "2017": [14.73, 13.07, 13.18, 13.72, 14.97, 16.52],
            "2018": [14.74, 13.19, 13.25, 13.75, 14.78, 16.41],
            "2019": [14.91, 13.06, 13.16, 13.77, 14.59, 16.05],
            "2020": [14.73, 13.11, 13.23, 13.85, 14.81, 16.38]
        };
    }

    average(year) {
        let sum = this.data[year].reduce((prev, cur) => prev + cur, 0);
        return sum / this.data[year].length;
    }

    minimum(year) {
        return Math.min(...this.data[year]);
    }

    maximum(year) {
        return Math.max(...this.data[year]);
    }

    predict(year) {
        let years = Object.keys(this.data).map(Number);
        let avgs = years.map(y => this.average(y));

        let xSum = years.reduce((a, b) => a + b, 0);
        let ySum = avgs.reduce((a, b) => a + b, 0);

        let xySum = years.reduce((sum, curr, idx) => sum + (curr * avgs[idx]), 0);
        let xxSum = years.reduce((sum, curr) => sum + Math.pow(curr, 2), 0);

        let n = years.length;

        let slope = ((n * xySum) - (xSum * ySum)) / ((n * xxSum) - Math.pow(xSum, 2));
        let intercept = (ySum - (slope * xSum)) / n;

        return (slope * year) + intercept;
    }
}

