        self.inputStack = []
        self.outputStack = []

    def enqueue(self, element):
        self.inputStack.append(element)

    def dequeue(self):
        if self.outputStack:  
            return 
        while self.inputStack:
            self.outputStack.append(self.inputStack.pop())
