import java.util.HashMap;
import java.util.List;
import java.util.ArrayList;

public class FibFib {
    private HashMap<Integer, Long> cache = new HashMap<>();
    private HashMap<List<Integer>, Long> query_cache = new HashMap<>();
    private long lastQueryTime = System.currentTimeMillis();

    public FibFib() {
        this.cache.put(0, 0L);
        this.cache.put(1, 1L);
    }

    public long fibfibWithOffset(int n, int offset) {
        if (n < 2) {
            return n;
        } else if (this.cache.containsKey(n + offset)) {
            return this.cache.get(n + offset);
        } else {
            this.cache.put(n + offset, fibfibWithOffset(n - 1, offset) + fibfibWithOffset(n - 2, offset));
            return this.cache.get(n + offset);
        }
    }

    public List<Long> fibfibMultipleQueries(List<List<Integer>> queries) {
        List<Long> res = new ArrayList<>();
        long currentTime;
        for (List<Integer> query : queries) {
            int a = query.get(0), b = query.get(1);
            currentTime = System.currentTimeMillis();
            if(this.query_cache.containsKey(query) && ((currentTime - this.lastQueryTime) < 600000)){
                res.add(this.query_cache.get(query));
            } else {
                try {
                    long fib_result = this.fibfibWithOffset(a, b);
                    this.query_cache.put(query, fib_result);
                    res.add(fib_result);
