        for (int num : l2) {
            if (num >= 0 && num % 2 == 0 && isPrime(num)) {
                evenPrimeNumbers.add(num);
            }
        }

        Collections.sort(evenPrimeNumbers, Collections.reverseOrder());
        return evenPrimeNumbers;
    }

    private static boolean isPrime(int num) {
        if (num <= 1) {
            return false;
        }
        if (num == 2) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }

        int sqr = (int) Math.sqrt(num) + 1;
        for (int divisor = 3; divisor < sqr; divisor += 2) {
            if (num % divisor == 0) {
                return false;
            }
        }
        return true;
    }
}
```

