```c++
#include <iostream>
using namespace std;

bool isPerfectNumber(int n) {
    int sum = 1;
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            if (i * i != n)
                sum = sum + i + n / i;
            else
                sum = sum + i;
        }
    } 
    if (sum == n && n != 1)
        return true;

    return false;
}

int rangeSum(int start, int end) {
    int sum = 0;
    for (int i = start; i <= end; i++) {
        if (isPerfectNumber(i)) {
            sum += i;
        }
    }
    return sum;
}

