```python

def find_key(input_structure, target_key, path=None):
    if path is None:
        path = []

    if isinstance(input_structure, dict):
        iterator = input_structure.items()
    elif isinstance(input_structure, (list, tuple)):
        iterator = enumerate(input_structure)
    else:
        return

    for key, value in iterator:
        new_path = list(path)
        new_path.append(key)

        if value == target_key:
            yield (new_path, 1)
        elif isinstance(value, (dict, list, tuple)):
            for result in find_key(value, target_key, new_path):
                yield result
        elif value == target_key:
            yield (new_path, 1)

def count_key(input_structure, target_key):
    count = 0
    paths = []
    for path, cnt in find_key(input_structure, target_key):
        count += cnt
        paths.append(path)

    return count, paths
```

