```go
package main

import (
    MQTT "github.com/eclipse/paho.mqtt.golang"
    "github.com/influxdata/influxdb/client/v2"
    "log"
    "os"
    "time"
)

const (
    DBServer = "http://localhost:8086"
    DBName   = "mqttDB"
)

type Payload struct {
    Topic   string
    Message string
}

func main() {
    // establish MQTT connection
    opts := MQTT.NewClientOptions().AddBroker("tcp://localhost:1883")
    opts.OnConnect = onConnect
    opts.OnConnectionLost = onConnectionLost
    c := MQTT.NewClient(opts)

    if token := c.Connect(); token.Wait() && token.Error() != nil {
        log.Println(token.Error())
        os.Exit(1)
    }

    // establish InfluxDB connection
    influxDB, err := client.NewHTTPClient(client.HTTPConfig{
        Addr: DBServer,
    })

    if err != nil {
        log.Printf("Error creating InfluxDB Client: ", err.Error())
    }

    // subscribe to topic
    token := c.Subscribe("#", 0, func(client MQTT.Client, msg MQTT.Message) {
        // save data to InfluxDB
        saveToDB(influxDB, msg.Topic(), string(msg.Payload()))
    })

    token.Wait()
}

func onConnect(c MQTT.Client) {
    log.Println("Connected to the MQTT broker.")
}

func onConnectionLost(c MQTT.Client, err error) {
    log.Printf("Connection lost: %v", err)
}

func saveToDB(clt client.Client, topic string, message string) {
    // create a new point batch
    bp, _ := client.NewBatchPoints(client.BatchPointsConfig{
        Database:  DBName,
        Precision: "s",
    })

    // create a point and add to batch
    tags := map[string]string{"topic": topic}
    fields := map[string]interface{}{
        "message": message,
    }

    pt, err := client.NewPoint("mqtt", tags, fields, time.Now())

    if err != nil {
        log.Fatalln("Error: ", err)
    }

    bp.AddPoint(pt)

    // write the batch
    clt.Write(bp)
}
```

