Here is a solution in Go using the built-in libraries to check the characters of the string:

```Go
import (
	"strings"
	"unicode"
)

func IsPalindrome(text string) bool {
	var letterRunes []rune

	for _, r := range text {
		if unicode.IsLetter(r) {
			letterRunes = append(letterRunes, unicode.ToLower(r))
		}
	}

	revText := reverseRunes(letterRunes)
	return strings.Compare(string(letterRunes), string(revText)) == 0
}

func reverseRunes(input []rune) []rune {
	if len(input) == 0 {
		return input
	}
	return append(reverseRunes(input[1:]), input[0])
