        int chunks = (upperLimit - lowerLimit) / cpuCount;
        for (int i = 0; i < cpuCount; i++) {
            int start = lowerLimit + chunks * i;
            int end = (i == cpuCount - 1) ? upperLimit : start + chunks - 1;
            Future<List<Integer>> future = service.submit(new PrimeTask(start, end));
            futures.add(future);
