def get_cumulative_sum_complex_dict(dict_obj, seen=None):
    if seen is None:
        seen = set()  # used to handle circular references
    if id(dict_obj) in seen:  # check if current object was already iterated over
        return 0
    seen.add(id(dict_obj))  
    cumulative_sum = 0
