```rust
// Define the function, it takes two strings as input and returns a Result with
// a String type or a Vec<String> type. This generic is necessary because
// Rust doesn't have same dynamical typing feature as Python.
pub fn advanced_evaluate_string(s: String, t: String) -> Result<(Vec<String>, String), &'static str> {

    // Match the 't' string. This is equivalent to the if-elif statements in Python.
    // Since strings are not copyable in Rust, we convert them into &str type first. 
    match t.as_str() {
        // If 't' is "split"
        "split" => {
            // If `s` contains ';'
            if s.contains(';') {
                // Split the string. Rust also returns an iterator which we collect into a vector.
                Ok((s.split(';').map(String::from).collect(), "".to_string()))
            // Else if `s` contains "::"
            } else if s.contains("::") {
                // Split the string, starting at "::"
                Ok((s.split("::").map(String::from).collect(), "".to_string()))
            } else {
                Err("String does not contain either of the split characters.")
            }
        }
        // If 't' is "caps"
        "caps" => {
            // Use an iterator to find uppercase letters at even indices.
            // The position (i) can be obtained by enumerate() function
            // Just like Python, but you need to make sure to convert to lowercase first for Unicode types.
            let mut sum = 0;
            for (i, c) in s.chars().enumerate() {
                if c.is_lowercase() && i % 2 == 0 {
                    sum += ((c.to_lowercase().next().unwrap() as u8) - ('a' as u8)) % 26;
                }
            }
            Ok((vec![], sum.to_string()))
        }
        // If 't' is "rev"
        "rev" => {
            // Rust does not support string reversal directly so we convert string into chars, reverse char and collect back to string
            Ok((vec![], s.chars().rev().collect()))
        }
        // If 't' is not matched
        _ => Err("Invalid operator."),
    }
}
