public class ComplexNumber {
    private final double real;
    private final double imaginary;

    // Constructor to create a complex number
    public ComplexNumber(double real, double imaginary) {
        this.real = real;
        this.imaginary = imaginary;
    }

    // Method to add two complex numbers
    public ComplexNumber add(ComplexNumber b) {
        double real = this.real + b.real;
        double imaginary = this.imaginary + b.imaginary;
        return new ComplexNumber(real, imaginary);
    }

    // Method to multiply two complex numbers
    public ComplexNumber multiply(ComplexNumber b) {
        double real = this.real * b.real - this.imaginary * b.imaginary;
        double imaginary = this.real * b.imaginary + this.imaginary * b.real;
        return new ComplexNumber(real, imaginary);
    }

    // Method to print the complex number
    @Override
    public String toString() {
        return "ComplexNumber{" +
                "real=" + real +
                ", imaginary=" + imaginary +
                '}';
    }
}
