int main() 
{ 
    // number of fibonacci number to generate
    int num = 50;
    unsigned long long fibonacci[num]; 

    // initial two numbers
    fibonacci[0] = 0; 
    fibonacci[1] = 1; 

    // generate fibonacci numbers
    for (int i = 2; i < num; i++) 
    { 
        fibonacci[i] = fibonacci[i-1] + fibonacci[i-2];

        // handle overflow 
        if(fibonacci[i] < fibonacci[i-2]) {
             cout << "Overflow occurred after the " << i << "th number" << endl;
             break;
        }
    } 

    // display fibonacci numbers
    for (int i = 0; i < num; i++) 
    {
        // if overflowed, break
        if(i > 0 && fibonacci[i] < fibonacci[i-1]) 
