```cpp
#include <iostream>
#include <string>
using namespace std;

int main() {
    string inputString;
    cout << "Please enter a string: ";
    cin >> inputString;

    string alphabets, digits;
    for (int i = 0; i < inputString.length(); ++i) {
        if (isdigit(inputString[i]))
            digits += inputString[i];
        else if (isalpha(inputString[i]))
            alphabets += inputString[i];
    }

    cout << "Alphabets: " << alphabets << endl;
    cout << "Digits: " << digits << endl;

    return 0;
}
