function square_rooting_and_conversion($n, $l, $base, $complexity, $precision) {
    if ($n < 1 || $base < 2 || $base > 16 || $precision < 0) {
        return -1;
    }

    $numbers = range($n, $n+$l+1);
    $result = [];

    if ($complexity == "squareroot") {
        $operations = array_map('sqrt', $numbers);
    } elseif ($complexity == "root") {
        if ($l < 1) {
            return -1;
        }
        $operations = array_map(function($num) use ($l) { return pow($num, 1/$l); }, $numbers);
    } else {
        return -1;
    }

    foreach($operations as $operation){
        $decimal = round($operation, $precision);
        $integer_part = floor($decimal);
        $fraction_part = fmod($decimal, 1);

        $integer_part = decimal_to_base($integer_part, $base);
        $fraction_part = fraction_to_base_n($fraction_part, $base, $precision);

        // output in binary form
        array_push($result, "0b" . $integer_part . "." . $fraction_part);
    }

    return $result;
}

function decimal_to_base($num, $base){
    $chars = "0123456789ABCDEF";
    if($num < $base){
        return $chars[$num];
    }else{
        return decimal_to_base(floor($num / $base), $base) . $chars[$num % $base];
    }
}

function fraction_to_base_n($num, $base, $precision){
    $chars = "0123456789ABCDEF";
    $result = "";
    for($i = 0; $i < $precision; $i++){
        $num = $num * $base;
        $digit = floor($num);
        $result .= $chars[$digit];
        $num -= $digit;
    }
    return $result;
