///     For p <= i: f[i] = f[i - 1] + f[i - 2] + f[i - 3] - f[i - m] - f[i - p]
///
/// - Parameters:
///     - n: The index of the number to return from the sequence
///     - m: The number to subtract from f[i] when i >= m
///     - p: The number to subtract from f[i] when i > p
/// - Returns: The nth number in the sequence
func fibfib(n: Int, m: Int, p: Int) -> Int {
    let MAX = max(n, m, p) + 1
    var f = [Int](repeating: 0, count: MAX)   // Create an array of size MAX filled with 0s
    f[2] = 1   // Set the third value to 1

    // Iterate over the rest of the array
    for i in 3..<MAX {
        // Calculate the base case
        f[i] = f[i - 1] + f[i - 2] + f[i - 3]

        // Subtract f[i - m] when i >= m
        if i >= m {
            f[i] -= f[i - m]
        }

        // Subtract f[i - p] when i > p
        if i > p {
            f[i] -= f[i - p]
        }
    }

    // Return the nth number in the sequence
    return f[n]
}
```
It calculates a modified Fibonacci sequence that subtracts earlier terms when the index is larger than m or p. It then returns the n-th number in this sequence.
The time complexity should be O(n), where n is the maximum of the input parameters. The space complexity should also be O(n), because we use an array of size n to store the sequence.

