    // if no prime numbers, return -1
    if(max_prime==-1) return -1;

    int sum_digits = 0;
    // Find sum of digits of max prime number
    while(max_prime!=0){
        int digit = max_prime%10;
        sum_digits += digit;
        max_prime /= 10;
