Here is an example of a simple program in C++ to manage an individual's nicknames and titles using a struct to represent a person.

```cpp
#include<iostream>
#include<vector>
#include<algorithm>
#include<exception>

struct Person {
    std::vector<std::string> nicknames;
    std::vector<std::string> titles;
};

class NameManager{
    public:
       void addNickname(Person &p, const std::string &nickname) {
            validateName(nickname);
            if(findNickOrTitle(p.nicknames, nickname)) throw std::runtime_error("Duplicate nickname.");
            p.nicknames.push_back(nickname);
       }

       void addTitle(Person &p, const std::string &title){
            validateName(title);
            if(findNickOrTitle(p.titles, title)) throw std::runtime_error("Duplicate title.");
            p.titles.push_back(title);
       }

       void updateNickname(Person &p, const std::string &oldNickname, const std::string &newNickname){
            validateName(newNickname);
            auto it = find(p.nicknames.begin(), p.nicknames.end(), oldNickname);
            if(it == p.nicknames.end()) throw std::runtime_error("Nickname not found.");
            *it = newNickname;
       }

       void deleteNickname(Person &p, const std::string &nickname){
            auto it = find(p.nicknames.begin(), p.nicknames.end(), nickname);
            if(it == p.nicknames.end()) throw std::runtime_error("Nickname not found.");
            p.nicknames.erase(it);
       }

    private:
        bool findNickOrTitle(const std::vector<std::string> &list, const std::string &item){
            return find(list.begin(), list.end(), item) != list.end();
        }

        void validateName(const std::string &name){
            if(name.empty()) throw std::runtime_error("Name cannot be empty.");
            for(char c : name){
                if(!isalpha(c) && c != ' ') throw std::runtime_error("Name contains invalid characters.");
            }
        }
};

int main(){
    try{
        Person p;
        NameManager nm;
        nm.addNickname(p, "Nick");
        nm.addTitle(p, "Mr");
        nm.updateNickname(p, "Nick", "Nick2"); // if this nickname doesn't exist, exception is thrown
        nm.deleteNickname(p, "Nick2"); // if this nickname doesn't exist, exception is thrown
    } catch (std::exception &ex){
        std::cerr << "Caught error: " << ex.what() << std::endl;
        return -1;
    }

    return 0;
