    def sort_func(l):
        for i in range(1, len(l)):
            j = i
            while j > 0 and l[j] < l[j-1]:
                l[j], l[j-1] = l[j-1], l[j]
                j -= 1
        return l

    common_elements = []
    # We will extract the first list and then remove its elements from it if they are not present in all other lists.
    first_list = lists[0]

    for el in first_list:
        if el not in common_elements:
            if all(el in lst for lst in lists[1:]):
                common_elements.append(el)

    common_elements = sort_func(common_elements)
