def find_divisors(n):
    divisors = [i for i in range(1,n+1) if n%i==0] 
    return divisors

def calc_values(n):
    divisors = find_divisors(n)
    sum_divisors = sum(divisors)
    product_divisors = 1
    for i in divisors:
        product_divisors *= i
    return (sum_divisors, product_divisors)

