Sure, here's a JavaScript function that generates all possible subsets of an array of size 'k'. This function uses a technique called backtracking to find all possible subsets.

```javascript
function subsets(arr, k) {
    let result = [];
    generateSubsets(arr, k, 0, []);

    function generateSubsets(arr, k, start, currentSet) {
      if(currentSet.length === k) {
          result.push([...currentSet]);
          return;
      }

      for(let i = start; i < arr.length; i++) {
          currentSet.push(arr[i]);
          generateSubsets(arr, k, i + 1, currentSet);
          currentSet.pop();
      }
    }

    return result;
}

