```python
class Rectangle:
    # Constructor
    def __init__(self, length, width, rgb_color):
        self.__length = length
        self.__width = width
        self.__rgb_color = rgb_color

    # Properties - Getters/Setters

    @property
    def length(self):
        return self.__length

    @length.setter
    def length(self, value):
        # check if the value is positive
        if value < 0:
            raise ValueError("Length must be positive")
        self.__length = value

    @property
    def width(self):
        return self.__width

    @width.setter
    def width(self, value):
        # check if the value is positive
        if value < 0:
            raise ValueError("Width must be positive")
        self.__width = value

    @property
    def rgb_color(self):
        return self.__rgb_color

    @rgb_color.setter
    def rgb_color(self, value):
        if not self.__is_valid_rgb(value):
            raise ValueError("Invalid RGB value")
        self.__rgb_color = value

    # Check if RGB value is valid
    @staticmethod
    def __is_valid_rgb(value):
        if isinstance(value, tuple) and len(value) == 3 and len([i for i in value if 0 <= i <= 255]) == 3:
            return True
        return False
