Here is a simple Python solution using the Tree structure to represent the hierarchical structure and the Node structure to represent individuals. 

```python
class Node:
    def __init__(self, name):
        self.name = name
        self.children = []

    def addChild(self, node):
        self.children.append(node)

class Tree:
    def __init__(self):
        self.root = None

    def add(self, parent_, child):
        parent = self.find(parent_)
        if parent is None:
            parent = Node(parent_)
            if self.root is None:
                self.root = parent
            else:
                raise ValueError(f"Orphan node {parent_}")
        parent.addChild(Node(child))

    def find(self, name, node=None):
        if node is None: 
            node = self.root
        if node.name == name:
            return node
        for child in node.children:
            found = self.find(name, child)
            if found is not None:
                return found
        return None

    def count(self, name):
        node = self.find(name)
        if node is not None:
            return self._count(node)
        else:
            return 0

    def _count(self, node):
        count = len(node.children)
        for child in node.children:
            count += self._count(child)
        return count

