def special_rounding(value, low, high):
    # Check if the input value is a valid number (integer or float)
    try:
        number = float(value)
    except ValueError:
        return "Error: Invalid input."

    # Check if the number is within the range
    if low <= number <= high:
        # Round the number towards zero
        if number > 0:
            if number - int(number) >= 0.5:
                result = int(number) + 1
            else:
                result = int(number)
        else:
            if abs(number - int(number)) >= 0.5:
                result = int(number) - 1
            else:
                result = int(number)

        return result

    else:
        return "Error: Out of range."

