In Perl, there's no built-in `map` function to process an array of arrays (or "2D array") directly. But, you can accomplish this with a combination of loop and push function. Here is the Perl equivalent:

```perl
use strict;
use warnings;

sub minimum_transformations {
    my @array_2D = @_;
    my @results = ();

    foreach my $arr (@array_2D) {
        my $modifications = 0;
        my $start = 0;
        my $end = @{$arr} - 1;

        while ($start < $end) {
            if ($arr->[$start] ne $arr->[$end]) {
                $modifications++;
            }
            $start++;
            $end--;
        }
        push @results, $modifications;
    }
    return @results;
}

my @result1 = minimum_transformations(
    [1,2,3,5,4,7,9,6],
    [1,2,3,4,3,2,2],
    [0,1,3,2,1,0]
);
